function block(b, slug, si, bi, s) {
  const id = `${slug}-${si}-${bi}`;
  if (b.type === 'card') {
    const check = slug === 'checklists';
    return `<div class="card" id="${id}">${b.kicker ? `<div class="meta">${nb(b.kicker)}</div>` : ''}${b.title ? `<h3 class="h3">${nb(b.title)}</h3>` : ''}
      <ul class="${check ? 'check' : ''}">${b.items.map((x, k) => `<li${check ? ` data-k="${id}-${k}" tabindex="0" role="checkbox" aria-checked="false"` : ''}>${item(x)}</li>`).join('')}</ul></div>`;
  }
  if (b.type === 'res') {
    const a = access(b.badge);
    const tags = tag(KIND[a.kind], a.kind) + (s && s.tag ? tag(s.tag, 'cat') : '') + a.extra.map(x => tag(x, 'cat')).join('');
    const inner = `<div class="top"><span class="ava" aria-hidden="true">${esc(b.name.charAt(0))}</span><h3>${esc(b.name)}</h3>${b.url ? EXT : ''}</div>
      <div class="tags">${tags}</div><p>${nb(b.desc)}</p>${b.url ? `<span class="url">${esc(host(b.url))}</span>` : ''}`;
    return b.url ? `<a class="res" id="${id}" href="${esc(b.url)}" target="_blank" rel="noopener nofollow">${inner}</a>` : `<div class="res" id="${id}">${inner}</div>`;
  }
  if (b.type === 'font') {
    const a = access(b.lic);
    const fam = `font-family:'${b.name.replace(/'/g, "\\'")}',var(--text)${b.name === 'Instrument Serif' ? ';font-weight:400' : ''}`;
    return `<div class="fcard" id="${id}"><div class="spec" style="${esc(fam)}" lang="${b.script === 'lat' ? 'en' : 'ru'}">${SPEC[b.script]}</div>
      <div class="top"><h3>${esc(b.name)}</h3><div class="tags">${tag(b.script === 'lat' ? 'Латиница' : 'Кириллица', 'cat')}${tag(KIND[a.kind], a.kind)}</div></div>
      <p>${nb(b.use)}</p>
      <div class="sizes"><div><small>Desktop</small><span>${sizeLines(b.d).map(esc).join('<br>')}</span></div><div><small>Mobile</small><span>${sizeLines(b.m).map(esc).join('<br>')}</span></div></div>
      ${a.extra.length ? `<div class="lic">${a.kind === 'paid' ? 'Где купить' : 'Лицензия'}: ${esc(a.extra.join(', '))}</div>` : ''}</div>`;
  }
  if (b.type === 'note') return `<div class="note" id="${id}">${nb(b.text)}</div>`;
  if (b.type === 'step') return `<div class="step" id="${id}">${slug === 'trends' && s ? `<div class="art">${(ART[/2027/.test(s.title) ? 't27' : 't26'] || [])[bi] || ''}</div>` : ''}<div class="n">${esc(b.num)}</div><h3 class="h3">${nb(b.title)}</h3><p>${nb(b.desc)}</p></div>`;
  if (b.type === 'table') {
    const hl = k => b.head && b.head[k] === 'Актуально' ? ' class="hl"' : '';
    return `<div class="tbl" id="${id}"><table>${b.head ? `<thead><tr>${b.head.map((h, k) => `<th${hl(k)}>${esc(h)}</th>`).join('')}</tr></thead>` : ''}<tbody>${b.rows.map(r => `<tr>${r.map((c, k) => `<td${hl(k)}>${nb(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }
  return '';
}

