function trends27() {
  const tp = PAGES.find(p => p.slug === 'trends'); if (!tp) return '';
  const si = tp.sections.findIndex(s => /2027/.test(s.title)); if (si < 0) return '';
  const cat = catSrc();
  return `<a class="t27" href="#/s/trends/trends-${si}">
    <div class="t27-txt"><span class="plate plate-olive">Прогноз</span><h2 class="t27-h">Дизайн-подходы 2027</h2><p>${nb('Куда движутся интерфейсы в следующем году: агенты, доверие к ИИ, авторский визуал и ещё 6 направлений.')}</p></div>
    <div class="t27-yr" aria-hidden="true">20<span>27</span></div>
    <div class="t27-act"><span class="btn btn-sec">Смотреть подходы ${ARROW}</span>${cat ? `<img class="t27-cat" src="${cat}" alt="" width="99" height="135">` : ''}</div></a>`;
}

